-- U4 Notifications: tables, constraints, indexes and row-level policies (BR40, NFR1.43, NFR3.13).
-- Conventions are those of 20261024_directory_schema.sql: schema-neutral (the migration runner sets the
-- session search path, every function pins its own with `set search_path from current`), uuid keys
-- generated by the database, `organization_id` on every table, an integer `version` on the record people
-- change at the same time, timestamps in UTC. Inside Notifications the tables are linked by composite
-- foreign keys (id plus organization), so a child row can never belong to another organization than its
-- parent. The links to other blocks (a notice to a Parent, a job to a Task, a recipient to a Family) are
-- typed ids with no foreign key (ADR-001), checked inside the named functions of the next files.
--
-- Who reads what. A parent reads, and may set `read_at` on, the notifications of the parent row linked to
-- their own account and nothing else: no other parent, teacher, admin or signed-out request reads a
-- notification, and an admin cannot read a parent's list. Reminder jobs, their recipients and their
-- attempts have row-level security and no policy at all: admins reach them through the named functions
-- (`reminder_list`, `reminder_retry`), which return counts and never a name or an address. Every other
-- change goes through the named functions of the next files. The service-role key gets no table right.

-- A planned simulated reminder for one task and one threshold. It serves all recipient families of the
-- task; its single simulated attempt covers all of them (BR40.4 to BR40.6).
create table reminder_jobs (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  task_id uuid not null,
  threshold text not null check (threshold in ('7d', '24h')),
  -- The task start the job was planned for; a changed start makes the job stale (BR40.5).
  task_starts_at timestamptz not null,
  scheduled_for timestamptz not null,
  status text not null default 'queued'
    check (status in ('queued', 'sent', 'retryable', 'retrying', 'stale', 'cancelled', 'terminal')),
  attempt integer not null default 0 check (attempt between 0 and 3),
  -- A short hash of the task, threshold and start: shown on the reminders screen, no family or person id.
  correlation_id text not null check (char_length(correlation_id) between 6 and 64 and correlation_id ~ '^[a-z0-9-]+$'),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, organization_id)
);
-- One live job per cause: a task and a threshold have one job while it is not stale or cancelled (BR40.4).
create unique index reminder_jobs_one_live on reminder_jobs (task_id, threshold)
  where status not in ('stale', 'cancelled');
create index reminder_jobs_task on reminder_jobs (task_id);
-- The due jobs of the tick, and the status filter of the reminders screen.
create index reminder_jobs_due on reminder_jobs (status, scheduled_for);
create index reminder_jobs_organization on reminder_jobs (organization_id, status, scheduled_for);
create trigger reminder_jobs_touch_version before update on reminder_jobs
  for each row execute function platform_touch_version();

-- A family that a reminder job is for. Removed when the family's place is removed or moved, or the
-- family is archived, deleted or anonymized (BR40.5); a removed row is history and never runs.
create table reminder_recipients (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  reminder_job_id uuid not null,
  family_id uuid not null,
  status text not null default 'active' check (status in ('active', 'removed')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (reminder_job_id, organization_id) references reminder_jobs (id, organization_id),
  unique (reminder_job_id, family_id)
);
create index reminder_recipients_family on reminder_recipients (family_id, status);

-- One simulated delivery attempt of a job (for all its active recipients). The number is 1 to 3 and unique
-- per job, which makes "at most 3 attempts per job" the database's own rule (BR40.6). No recipient
-- address and no message text is stored: delivery is simulated and labelled so everywhere.
create table reminder_attempts (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  reminder_job_id uuid not null,
  attempt_number integer not null check (attempt_number between 1 and 3),
  outcome text not null check (outcome in ('simulated_sent', 'simulated_retry', 'simulated_failed')),
  attempted_at timestamptz not null default now(),
  foreign key (reminder_job_id, organization_id) references reminder_jobs (id, organization_id),
  unique (reminder_job_id, attempt_number)
);

-- One message for one parent (BR40.1, BR40.6). It holds no name, contact or note: the Hungarian title and
-- the link are built from the target when the list is read (BR40.2).
create table notifications (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  parent_id uuid not null,
  kind text not null check (kind in (
    'sign_up_confirmed', 'swap_requested', 'swap_decided', 'cancellation_decided', 'place_removed',
    'reminder_7d', 'reminder_24h')),
  target_type text not null check (target_type in ('task', 'change_request')),
  target_ref uuid not null,
  -- The task the message concerns (for a change request, the requester's task): the list builds the title
  -- from it and tests whether a reminder is stale.
  task_id uuid not null,
  task_starts_at timestamptz not null,
  reminder_job_id uuid,
  -- Event notices: kind, target, parent and the assignment or request id with its version; reminders: kind,
  -- job, parent and task start. A replay creates nothing twice; a later genuine repeat has another key.
  dedupe_key text not null unique check (char_length(dedupe_key) between 1 and 400),
  read_at timestamptz,
  created_at timestamptz not null default now(),
  -- A reminder kind belongs to a job and an event kind does not.
  check ((kind in ('reminder_7d', 'reminder_24h')) = (reminder_job_id is not null)),
  -- Not checked while reminder_job_id is empty (an event notice).
  foreign key (reminder_job_id, organization_id) references reminder_jobs (id, organization_id)
);
-- The parent's list, newest first, and the task lookups of the tick and the lifecycle.
create index notifications_parent on notifications (parent_id, created_at desc);
create index notifications_task on notifications (task_id);
create index notifications_job on notifications (reminder_job_id) where reminder_job_id is not null;

-- Read once: a repeat keeps the first time (BR40.3). The table policy lets a parent set read_at on their own
-- rows; this trigger stops it from being changed or cleared afterwards, whoever writes it.
create or replace function notifications_guard_update() returns trigger
language plpgsql set search_path from current
as $$ begin
  if old.read_at is not null and new.read_at is distinct from old.read_at then
    raise exception 'notifications: read_at is set once' using errcode = '23514';
  end if;
  return new;
end $$;
create trigger notifications_guard_update before update on notifications
  for each row execute function notifications_guard_update();

-- ---------------------------------------------------------------------------------------------------
-- The reader of the policies: the parent row linked to the signed-in account, in an active session. One
-- account is linked to at most one parent (unique account_id), so the value is a single id; the policies
-- ask for it once per statement (an initplan), not once per row.
-- ---------------------------------------------------------------------------------------------------
create or replace function notification_actor_parent() returns uuid
language sql stable security definer set search_path from current
as $$
  select p.id from parents p
   where p.account_id = auth.uid() and p.status = 'active' and current_session_is_active()
$$;

-- ---------------------------------------------------------------------------------------------------
-- Row-level security.
-- ---------------------------------------------------------------------------------------------------
alter table notifications enable row level security;
alter table reminder_jobs enable row level security;
alter table reminder_recipients enable row level security;
alter table reminder_attempts enable row level security;

create policy notifications_read on notifications for select to authenticated
  using (parent_id = (select notification_actor_parent()));
-- A parent may change read_at on their own rows: the column right below is the only update right, and the
-- trigger above keeps it to a single change (BR40.3).
create policy notifications_mark_read on notifications for update to authenticated
  using (parent_id = (select notification_actor_parent()))
  with check (parent_id = (select notification_actor_parent()));

revoke all on notifications, reminder_jobs, reminder_recipients, reminder_attempts
  from public, anon, authenticated, service_role;
grant select on notifications to authenticated;
grant update (read_at) on notifications to authenticated;

revoke all on function notifications_guard_update(), notification_actor_parent()
  from public, anon, authenticated, service_role;
grant execute on function notification_actor_parent() to authenticated;
